1	import { rollDice, type Action, type Pack, type Predicate, type Table, type TargetRef, type Trigger } from "@runlog/rules-schema";
2	import type { RunEvent } from "./events.ts";
3	import { resolveTargeting } from "./targeting.ts";
4	import { eligibleTargets } from "./eligibility.ts";
5	import { withinBound } from "./bounds.ts";
6	import { currentSubject } from "./reduce.ts";
7	import { clockOfUnit, elapsedMs } from "./clock.ts";
8	import type { Clock, InputRequest, RunState, TriggerRef } from "./types.ts";
9	
10	/**
11	 * Running a pack's actions against run state.
12	 *
13	 * Two design choices carry most of the weight here.
14	 *
15	 * **Execution is interruptible.** A pack can ask for a die roll the player
16	 * wants to make with real dice, or for a judgment about the work that the
17	 * engine has no way to see. So the executor stops and asks, rather than
18	 * inventing an answer.
19	 *
20	 * **Resuming re-runs from the beginning**, replaying answers already given.
21	 * Actions are pure given (state, answers), so the second pass retraces exactly
22	 * the same path and stops at the next unanswered question. That removes any
23	 * need to freeze a call stack, and it means a half-finished resolution commits
24	 * nothing: events land only once the whole tree completes. An entry either
25	 * resolves or it does not.
26	 */
27	
28	export type AnswerValue = string | number | boolean;
29	
30	export interface ExecContext {
31	  /** Answers already given, keyed by the deterministic key of each request. */
32	  answers: Record<string, AnswerValue>;
33	  /**
34	   * When present, rolls are generated instead of asked for. Physical dice are
35	   * the default, so most of the time this is absent on purpose.
36	   */
37	  random?: () => number;
38	  /**
39	   * Answer keys whose values the app produced rather than the player.
40	   *
41	   * The log records how every roll came about, and a convenience button must
42	   * not be able to launder a generated number into the record as a physical
43	   * one. Provenance is the whole reason the field exists.
44	   */
45	  generatedAnswers?: readonly string[];
46	  /**
47	   * Marks a random source as coming from the run's seed rather than from
48	   * whatever the browser had lying around, so the log can say which.
49	   */
50	  seeded?: boolean;
51	  /** Timestamp stamped on every generated event. */
52	  now: string;
53	  /** Distinguishes executions so their keys cannot collide. */
54	  keyPrefix?: string;
55	}
56	
57	export interface ExecResult {
58	  status: "done" | "awaiting";
59	  /** The complete event list for this execution. Commit only when done. */
60	  events: RunEvent[];
61	  /** What is needed to carry on. */
62	  request?: InputRequest;
63	}
64	
65	/**
66	 * Thrown to unwind out to the top when the player must answer something.
67	 *
68	 * Written out longhand rather than as a parameter property: the CLI runs on
69	 * plain Node with `--experimental-strip-types`, which erases annotations
70	 * without evaluating them and so cannot desugar `constructor(readonly x)`.
71	 * Keeping the engine loadable that way is what lets someone validate and test
72	 * a pack with `npx` and no build step.
73	 */
74	class NeedInput extends Error {
75	  readonly request: InputRequest;
76	
77	  constructor(request: InputRequest) {
78	    super(`awaiting ${request.kind}`);
79	    this.request = request;
80	  }
81	}
82	
83	interface Frame {
84	  pack: Pack;
85	  state: RunState;
86	  ctx: ExecContext;
87	  events: RunEvent[];
88	  /** Values bound by `roll` and `prompt`, readable by `branch`. */
89	  vars: Map<string, AnswerValue>;
90	  /** The subject a consequence is currently aimed at. */
91	  target: number | null;
92	}
93	
94	const at = (f: Frame) => f.ctx.now;
95	
96	function need(f: Frame, request: InputRequest): AnswerValue {
97	  const existing = f.ctx.answers[request.key];
98	  if (existing !== undefined) return existing;
99	  throw new NeedInput(request);
100	}
101	
102	/* ------------------------------------------------------------------ *
103	 * Predicates
104	 * ------------------------------------------------------------------ */
105	
106	/**
107	 * Compare a value against a bound, resolving any counter or dial it names.
108	 *
109	 * The counter variants exist because a rule like "roll a d6 against the number
110	 * of consequences you have suffered" cannot be written with literals: the
111	 * threshold is whatever the run has accumulated. The resource variants exist
112	 * for the other half of that: a threshold that is the player's own answer to
113	 * how often a thing should happen.
114	 */
115	const compare = withinBound;
116	
117	/**
118	 * The clock a `clockRan`/`clockRanOver` predicate names: the current unit's
119	 * own clock for `"unit"`, or the first clock in the current unit carrying
120	 * that label. Neither is a declared id -- a clock is just whatever a `clock`
121	 * config or a `startTimer`/`startStopwatch` action happened to call it.
122	 */
123	function namedClock(state: RunState, name: string): Clock | undefined {
124	  if (name === "unit") return clockOfUnit(state, state.unit);
125	  return state.clocks.find((c) => c.unit === state.unit && c.label === name);
126	}
127	
128	function resolveSubjectRef(f: Frame, ref: TargetRef | undefined): number[] {
